/* global document, Office, fetch, navigator, console */

const FLASK_URL = "https://localhost:5000/check";

let CURRENT_THRESHOLDS = { red: 60, amber: 75 };

const DEFAULT_SUBSCORE_ORDER = ["grammar", "professionalism", "clarity", "accuracy"];
const DEFAULT_SUBSCORE_WEIGHTS = { grammar: 20, professionalism: 20, clarity: 25, accuracy: 35 };
const DEFAULT_SUBSCORE_LABELS = {
  grammar: "Grammar",
  professionalism: "Professionalism",
  clarity: "Clarity",
  accuracy: "Accuracy"
};

let LAST_DIAGNOSTIC = null;

// Cache for the quoted thread HTML, captured on the first "Use this draft"
// click and reused on every subsequent click. We can't safely re-extract on
// each click because Outlook strips its auto-generated quote markers
// (id="divRplyFwdMsg" etc.) after our setAsync, so the second extraction
// comes back empty and the thread vanishes. Reset on each runCheck so a
// fresh analysis on a different email picks up the new thread.
let cachedQuotedHtml = null;

Office.onReady((info) => {
  if (info.host === Office.HostType.Outlook) {
    runCheck();
    document.getElementById("recheck-button").onclick = runCheck;
    document.getElementById("copy-rewrite-button").onclick = copyRewrite;
    document.getElementById("insert-rewrite-button").onclick = insertRewrite;
  }
});

async function runCheck() {
  showLoading();
  cachedQuotedHtml = null;  // Fresh check = potentially different email

  try {
    const rawBody = await getDraftBody();
    const { draft, history } = splitDraftAndHistory(rawBody);

    const response = await fetch(FLASK_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        email: draft,
        client_email: history
      })
    });

    if (!response.ok) {
      throw new Error(`Server returned ${response.status}`);
    }

    const result = await response.json();
    renderResult(result);
    renderDiagnostic();
  } catch (err) {
    showError(`Couldn't reach the Compass service. Make sure Flask is running at ${FLASK_URL}. Details: ${err.message}`);
    renderDiagnostic();
  }
}

// ─────────────────────────────────────────────────────────────────
// Reply-thread separation with diagnostic capture
// ─────────────────────────────────────────────────────────────────
function splitDraftAndHistory(rawBody) {
  if (!rawBody) {
    LAST_DIAGNOSTIC = {
      rawLength: 0, preview: "(empty)", preview2: "",
      matchedPattern: "N/A — body was empty", matchedSample: "",
      splitIndex: 0, draftLength: 0, historyLength: 0
    };
    return { draft: "", history: "" };
  }

  const markers = [
    /\n\s*From:\s.+\n\s*Sent:/i,
    /\n\s*From:\s.+\n\s*\u2502*\s*Sent:/i,
    /\nFrom:\s.+\[mailto:/i,
    /\nFrom:\s.{1,200}@.+/i,
    /\n\s*_{10,}/,
    /\n\s*-{20,}/,
    /\n\s*={20,}/,
    /\n\s*On .{1,200}\bwrote:/i,
    /\n\s*On .{1,200}\bat\b.{1,80}\bwrote:/i,
    /\n\s*-+\s*Original Message\s*-+/i,
    /\n\s*-+\s*Forwarded Message\s*-+/i,
    /\n\s*Sent from my (iPhone|iPad|Samsung|Android|mobile|BlackBerry)/i,
    /\n\s*Get Outlook for (iOS|Android)/i,
    /\n\s*To:\s.+\n\s*Subject:/i,
  ];

  let earliest = rawBody.length;
  let matchedPattern = null;
  let matchedSample = null;

  for (const marker of markers) {
    const match = rawBody.match(marker);
    if (match && match.index < earliest) {
      earliest = match.index;
      matchedPattern = marker.toString();
      matchedSample = match[0].substring(0, 80);
    }
  }

  const draft = rawBody.substring(0, earliest).trim();
  const history = rawBody.substring(earliest).trim();

  LAST_DIAGNOSTIC = {
    rawLength: rawBody.length,
    preview: rawBody.substring(0, 600),
    preview2: rawBody.length > 600 ? rawBody.substring(600, 1200) : "",
    matchedPattern: matchedPattern || "NONE — no quote marker found",
    matchedSample: matchedSample ? JSON.stringify(matchedSample) : "(none)",
    splitIndex: earliest,
    draftLength: draft.length,
    historyLength: history.length
  };

  console.log("[Compass diagnostic]", LAST_DIAGNOSTIC);
  return { draft, history };
}

function renderDiagnostic() {
  const section = document.getElementById("diagnostic-section");
  const content = document.getElementById("diagnostic-content");
  if (!section || !content) return;

  if (!LAST_DIAGNOSTIC) {
    section.style.display = "none";
    return;
  }

  const d = LAST_DIAGNOSTIC;
  const lines = [
    `Raw body length:        ${d.rawLength}`,
    `Marker matched:         ${d.matchedPattern}`,
    `Marker sample (first 80 chars): ${d.matchedSample}`,
    `Split index:            ${d.splitIndex} of ${d.rawLength}`,
    `Draft length:           ${d.draftLength}`,
    `History length:         ${d.historyLength}`,
    ``,
    `─── RAW BODY — first 600 chars ───`,
    d.preview || "(empty)",
  ];
  if (d.preview2) {
    lines.push(``, `─── RAW BODY — chars 600-1200 ───`, d.preview2);
  }
  content.textContent = lines.join("\n");
  section.style.display = "block";
}

function getDraftBody() {
  return new Promise((resolve, reject) => {
    Office.context.mailbox.item.body.getAsync(
      Office.CoercionType.Text,
      (asyncResult) => {
        if (asyncResult.status === Office.AsyncResultStatus.Succeeded) {
          resolve(asyncResult.value || "");
        } else {
          reject(new Error("Couldn't read the draft body."));
        }
      }
    );
  });
}

function showLoading() {
  document.getElementById("status-section").style.display = "block";
  document.getElementById("results-section").style.display = "none";
  document.getElementById("error-section").style.display = "none";
  document.getElementById("recheck-button").style.display = "none";
}

function showError(message) {
  document.getElementById("status-section").style.display = "none";
  document.getElementById("results-section").style.display = "none";
  document.getElementById("error-section").style.display = "block";
  document.getElementById("error-text").textContent = message;
  document.getElementById("recheck-button").style.display = "block";
}

function renderResult(result) {
  document.getElementById("status-section").style.display = "none";
  document.getElementById("error-section").style.display = "none";
  document.getElementById("results-section").style.display = "block";
  document.getElementById("recheck-button").style.display = "block";

  if (result.thresholds && typeof result.thresholds.red === "number" && typeof result.thresholds.amber === "number") {
    CURRENT_THRESHOLDS = result.thresholds;
  }

  const statusEl = document.getElementById("overall-status");
  const status = (result.overall_status || "GREEN").toUpperCase();
  statusEl.className = "overall-status " + status.toLowerCase();

  const statusLabels = {
    RED: "🛑 Do not send — needs your attention",
    AMBER: "⚠️ Review before sending",
    GREEN: "✅ Looks good"
  };
  statusEl.textContent = statusLabels[status] || status;

  renderQualityScore(result.quality_score);
  renderSubscores(result);

  renderFlagGroup("red-flags-block", "red-flags-list", result.red_flags || []);
  renderFlagGroup("amber-flags-block", "amber-flags-list", result.amber_flags || []);
  renderFlagGroup("positive-notes-block", "positive-notes-list", result.positive_notes || []);

  renderSuggestedDraft(result.suggested_draft || "", result.suggested_draft_kind || "rewrite");
}

function renderQualityScore(score) {
  const block = document.getElementById("quality-score-block");
  const valueEl = document.getElementById("score-value");
  const fillEl = document.getElementById("score-bar-fill");
  const thresholdsEl = document.getElementById("score-thresholds");

  if (score === undefined || score === null) {
    block.style.display = "none";
    return;
  }

  const clamped = Math.max(0, Math.min(100, Number(score) || 0));
  valueEl.textContent = clamped + "%";
  fillEl.style.width = clamped + "%";
  fillEl.style.backgroundColor = colorForScore(clamped);

  thresholdsEl.textContent = `Block below ${CURRENT_THRESHOLDS.red}% · Pass at ${CURRENT_THRESHOLDS.amber}%+`;
  block.style.display = "block";
}

function colorForScore(score) {
  if (score < CURRENT_THRESHOLDS.red) return "#c64545";
  if (score < CURRENT_THRESHOLDS.amber) return "#c9a961";
  return "#5e9e5e";
}

function renderSubscores(result) {
  const block = document.getElementById("subscores-block");
  const list = document.getElementById("subscores-list");
  list.innerHTML = "";

  const subscores = result.subscores;
  if (!subscores || typeof subscores !== "object") {
    block.style.display = "none";
    return;
  }

  const weights = (result.subscore_weights && typeof result.subscore_weights === "object")
    ? result.subscore_weights
    : DEFAULT_SUBSCORE_WEIGHTS;
  const labels = (result.subscore_labels && typeof result.subscore_labels === "object")
    ? result.subscore_labels
    : DEFAULT_SUBSCORE_LABELS;
  const order = (result.subscore_weights && typeof result.subscore_weights === "object")
    ? Object.keys(result.subscore_weights)
    : DEFAULT_SUBSCORE_ORDER;

  let rendered = 0;
  order.forEach((key) => {
    if (subscores[key] === undefined || subscores[key] === null) return;
    const value = Math.max(0, Math.min(100, Number(subscores[key]) || 0));
    const weight = weights[key];
    const label = labels[key] || key;
    const color = colorForScore(value);

    const li = document.createElement("li");
    li.className = "subscore-item";

    const row = document.createElement("div");
    row.className = "subscore-row";

    const labelEl = document.createElement("span");
    labelEl.className = "subscore-label";
    labelEl.textContent = label;
    row.appendChild(labelEl);

    if (weight !== undefined) {
      const weightEl = document.createElement("span");
      weightEl.className = "subscore-weight";
      weightEl.textContent = weight + "%";
      row.appendChild(weightEl);
    }

    const valueEl = document.createElement("span");
    valueEl.className = "subscore-value";
    valueEl.textContent = value + "%";
    row.appendChild(valueEl);

    const track = document.createElement("div");
    track.className = "subscore-bar-track";
    const fill = document.createElement("div");
    fill.className = "subscore-bar-fill";
    fill.style.width = value + "%";
    fill.style.backgroundColor = color;
    track.appendChild(fill);

    li.appendChild(row);
    li.appendChild(track);
    list.appendChild(li);
    rendered++;
  });

  block.style.display = rendered > 0 ? "block" : "none";
}

function renderFlagGroup(blockId, listId, items) {
  const block = document.getElementById(blockId);
  const list = document.getElementById(listId);
  list.innerHTML = "";

  if (!items || items.length === 0) {
    block.style.display = "none";
    return;
  }

  block.style.display = "block";

  items.forEach((item) => {
    const li = document.createElement("li");
    const primaryText = item.issue || item.note || "(no text)";
    const secondaryText = item.action || "";

    const issueDiv = document.createElement("div");
    issueDiv.className = "flag-issue";
    issueDiv.textContent = primaryText;
    li.appendChild(issueDiv);

    if (secondaryText) {
      const actionDiv = document.createElement("div");
      actionDiv.className = "flag-action";
      actionDiv.textContent = secondaryText;
      li.appendChild(actionDiv);
    }
    list.appendChild(li);
  });
}

function renderSuggestedDraft(draftText, kind) {
  const block = document.getElementById("suggested-draft-block");
  const textEl = document.getElementById("suggested-draft-text");
  const headingEl = document.getElementById("suggested-heading-text");
  const introEl = document.getElementById("suggested-intro-text");
  const buttonEl = document.getElementById("insert-button-text");

  if (!draftText || !draftText.trim()) {
    block.style.display = "none";
    return;
  }

  const isPlaceholder = kind === "placeholder";
  if (isPlaceholder) {
    headingEl.textContent = "Draft with placeholders to fill in";
    introEl.textContent = "I've drafted this in your voice — fill in the [BRACKETS] with the missing details before sending.";
    buttonEl.textContent = "Use this template";
  } else {
    headingEl.textContent = "Suggested rewrite";
    introEl.textContent = "A draft that would pass this check, in your voice.";
    buttonEl.textContent = "Use this draft";
  }

  textEl.textContent = draftText;
  block.style.display = "block";
}

function copyRewrite() {
  const text = document.getElementById("suggested-draft-text").textContent;
  if (!text) return;

  const btn = document.getElementById("copy-rewrite-button");
  const originalText = btn.textContent;

  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(
      () => { btn.textContent = "Copied ✓"; setTimeout(() => { btn.textContent = originalText; }, 1500); },
      () => { btn.textContent = "Copy failed"; setTimeout(() => { btn.textContent = originalText; }, 1500); }
    );
  } else {
    const temp = document.createElement("textarea");
    temp.value = text;
    document.body.appendChild(temp);
    temp.select();
    try { document.execCommand("copy"); btn.textContent = "Copied ✓"; }
    catch (e) { btn.textContent = "Copy failed"; }
    document.body.removeChild(temp);
    setTimeout(() => { btn.textContent = originalText; }, 1500);
  }
}

// ─────────────────────────────────────────────────────────────────
// Insert rewrite — preserves the quoted thread across multiple clicks
// ─────────────────────────────────────────────────────────────────
// On the FIRST click in a check session, we read the current body, extract
// the quoted thread once, and cache it in `cachedQuotedHtml`. On every
// SUBSEQUENT click we skip the get+extract step entirely and reuse the
// cached quote — Outlook strips its own quote markers (id="divRplyFwdMsg"
// etc.) after our setAsync, so re-extracting would lose the thread.
function insertRewrite() {
  const text = document.getElementById("suggested-draft-text").textContent;
  if (!text) return;

  const btn = document.getElementById("insert-rewrite-button");
  const btnTextEl = document.getElementById("insert-button-text");
  const originalText = btnTextEl.textContent;
  btn.disabled = true;
  btnTextEl.textContent = "Inserting...";

  const rewriteHtml = formatRewriteAsHtml(text);

  const doSet = (quotedHtml) => {
    const newBody = quotedHtml ? rewriteHtml + quotedHtml : rewriteHtml;
    Office.context.mailbox.item.body.setAsync(
      newBody,
      { coercionType: Office.CoercionType.Html },
      (setResult) => {
        const ok = setResult.status === Office.AsyncResultStatus.Succeeded;
        finishInsert(btn, btnTextEl, originalText, ok ? "Inserted ✓" : "Insert failed");
      }
    );
  };

  if (cachedQuotedHtml !== null) {
    // Subsequent click — use the cached quote, skip re-extraction
    doSet(cachedQuotedHtml);
    return;
  }

  // First click — read the body, extract the quote, cache it
  Office.context.mailbox.item.body.getAsync(
    Office.CoercionType.Html,
    (htmlResult) => {
      if (htmlResult.status !== Office.AsyncResultStatus.Succeeded) {
        finishInsert(btn, btnTextEl, originalText, "Read failed");
        return;
      }
      const htmlBody = htmlResult.value || "";
      cachedQuotedHtml = extractQuotedHtml(htmlBody) || "";
      doSet(cachedQuotedHtml);
    }
  );
}

function finishInsert(btn, btnTextEl, originalText, message) {
  btn.disabled = false;
  btnTextEl.textContent = message;
  setTimeout(() => { btnTextEl.textContent = originalText; }, 1800);
}

// ─────────────────────────────────────────────────────────────────
// Format the plain-text rewrite into Outlook-native HTML
// ─────────────────────────────────────────────────────────────────
// Switched from <p>...</p><p>...</p> to <div>...</div><div><br></div>
// because Outlook collapses <p> margins to zero in many compose contexts,
// which makes the rewrite read as one tight block. The div + br pattern
// is Outlook's own native format and guarantees a visible blank line
// between greeting / body / sign-off, matching what the user sees when
// they press Enter twice in compose.
function formatRewriteAsHtml(text) {
  const paragraphs = text.split(/\n{2,}/);
  const parts = [];

  paragraphs.forEach((paragraph, i) => {
    if (i > 0) {
      // Visible blank line between paragraphs
      parts.push("<div><br></div>");
    }
    const escaped = paragraph
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
    // Each line inside a paragraph becomes its own <div>; empty lines
    // become <div><br></div> so blank inner lines also render visibly.
    escaped.split("\n").forEach((line) => {
      parts.push(line ? `<div>${line}</div>` : "<div><br></div>");
    });
  });

  return parts.join("");
}

function extractQuotedHtml(htmlBody) {
  if (!htmlBody) return "";
  const patterns = [
    /<div[^>]*id=["']?divRplyFwdMsg["']?[^>]*>/i,
    /<div[^>]*id=["']?appendonsend["']?[^>]*>/i,
    /<div[^>]*class=["']?[^"']*OutlookMessageHeader[^"']*["']?[^>]*>/i,
    /<div[^>]*class=["']?[^"']*x_OutlookMessageHeader[^"']*["']?[^>]*>/i,
    /<hr[^>]*id=["']?stopSpelling["']?[^>]*>/i,
    /<hr[^>]*tabindex=["']?-1["']?[^>]*>/i,
    /<blockquote[^>]*type=["']?cite["']?[^>]*>/i,
    /<div[^>]*style=["'][^"']*border-top:[^"']*solid[^"']*["'][^>]*>(?=[\s\S]{0,500}From:)/i,
    /<p[^>]*>\s*<b[^>]*>\s*From:\s*<\/b>/i,
    /<p[^>]*>\s*From:\s.+@.+<\/p>/i
  ];

  let earliestIndex = -1;
  for (const pattern of patterns) {
    const match = htmlBody.match(pattern);
    if (match && match.index !== undefined) {
      if (earliestIndex === -1 || match.index < earliestIndex) {
        earliestIndex = match.index;
      }
    }
  }
  return earliestIndex >= 0 ? htmlBody.substring(earliestIndex) : "";
}
